/**
 * Generates src/lib/db-template.ts from the local SQLite database.
 *
 * Why: Netlify Functions run on a read-only filesystem (only /tmp is
 * writable) and the repository does not ship dev.db. Embedding a compressed
 * copy lets the app materialise a working database at runtime instead of
 * crashing with "Cannot open database because the directory does not exist".
 *
 * The generated file is committed, so a fresh checkout / CI build that has no
 * dev.db still ships a valid template.
 *
 * Run automatically as part of `npm run build`.
 */
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";

const root = process.cwd();
const source = path.join(root, "dev.db");
const output = path.join(root, "src", "lib", "db-template.ts");

if (!fs.existsSync(source)) {
  console.warn(
    "[db-template] dev.db not found - keeping the committed template (if any)."
  );
  process.exit(0);
}

const raw = fs.readFileSync(source);
const b64 = zlib.gzipSync(raw, { level: 9 }).toString("base64");

const contents = `/**
 * AUTO-GENERATED by scripts/prepare-db-template.mjs -- do not edit by hand.
 * Compressed (gzip + base64) copy of the SQLite database, used to bootstrap a
 * writable database on hosts with a read-only filesystem (Netlify Functions).
 */
export const DB_TEMPLATE_B64 =
  "${b64}";
export const DB_TEMPLATE_BYTES = ${raw.length};
`;

fs.writeFileSync(output, contents);
console.log(
  `[db-template] wrote src/lib/db-template.ts (${b64.length} chars, ${raw.length} raw bytes)`
);
